import{_ as e,o as r,c as i,a3 as s}from"./chunks/framework.iKZ1V-y0.js";const h=JSON.parse('{"title":"Logistics Principles and Frontier Research","description":"","frontmatter":{"lang":"en-US","translationSource":{"title":"物流原理与前沿研究","archivedAt":"2026-10-23T14:20:34.857Z","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=Ul3PjfHfEH7t9ofd3SfA1L","scope":"page"}},"headers":[],"relativePath":"logistics/src/page-Ul3PjfHfEH7t9ofd3SfA1L.md","filePath":"logistics/src/page-Ul3PjfHfEH7t9ofd3SfA1L.md","lastUpdated":null}'),o={name:"logistics/src/page-Ul3PjfHfEH7t9ofd3SfA1L.md"};function t(n,a,l,c,p,u){return r(),i("div",null,[...a[0]||(a[0]=[s('<div class="logistics-content"><span class="logistics-source-anchor" id="物流原理与前沿研究" aria-hidden="true"></span><h1 id="logistics-principles-and-frontier-research" tabindex="-1">Logistics Principles and Frontier Research <a class="header-anchor" href="#logistics-principles-and-frontier-research" aria-label="Permalink to &quot;Logistics Principles and Frontier Research&quot;">​</a></h1><blockquote><p>Source page ID: <code>Ul3PjfHfEH7t9ofd3SfA1L</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=Ul3PjfHfEH7t9ofd3SfA1L" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p><span class="mark-red"><strong>Severely unmaintained. Discuss whether this page&#39;s subpage organization is appropriate.</strong></span></p><p><span id="source-block-3MTsTMyenCW20YTMnFSi65"></span></p><span class="logistics-source-anchor" id="流量转化" aria-hidden="true"></span><h2 id="flow-rate-transformation" tabindex="-1">Flow-Rate Transformation <a class="header-anchor" href="#flow-rate-transformation" aria-label="Permalink to &quot;Flow-Rate Transformation&quot;">​</a></h2><p><span id="source-block-wO7xPIiHDJwfeAtqFW4VJE"></span></p><span class="logistics-source-anchor" id="均匀性与极差" aria-hidden="true"></span><h2 id="uniformity-and-range" tabindex="-1">Uniformity and Range <a class="header-anchor" href="#uniformity-and-range" aria-label="Permalink to &quot;Uniformity and Range&quot;">​</a></h2><p><span id="source-block-f5f4WE5OyQHLDbhWbKgmAv"></span></p><span class="logistics-source-anchor" id="滤波器" aria-hidden="true"></span><h2 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h2><p>Narrow-sense filter: converts a nonuniform input sequence to a more uniform sequence, e.g. 10110 10011 → 10110 10110. Sometimes called a flow stabilizer.</p><p>With full-belt input, equivalent to a comparatively uniform limiter.</p><p>Broad-sense filter: low-pass diverts sequence flow exceeding a specified range elsewhere, usually inserting it into a below-range sequence or outside the structure. High-pass is the opposite.</p><p><span id="source-block-9j2XLqzFcpwJ8W5QQIYeRK"></span></p><span class="logistics-source-anchor" id="整流器" aria-hidden="true"></span><h2 id="flow-regularizers" tabindex="-1">Flow Regularizers <a class="header-anchor" href="#flow-regularizers" aria-label="Permalink to &quot;Flow Regularizers&quot;">​</a></h2><p>Narrow-sense flow regularizer: converts input to consecutive 1/0 runs, e.g. 10110 10011 → 11100 11100.</p><p>With full-belt input, transmits a blocking signal with consecutive 1/0 runs upstream.</p><p>Broad-sense flow regularizer: converts input into a specifically structured flow, typically continuous flow alternating with 0 flow, or particular sequences such as perfectly uniform ones.</p><p><span id="source-block-dey4t7kblTAWoIHHqzUYE7"></span></p><span class="logistics-source-anchor" id="溢流器" aria-hidden="true"></span><h2 id="overflow-routers" tabindex="-1">Overflow Routers <a class="header-anchor" href="#overflow-routers" aria-label="Permalink to &quot;Overflow Routers&quot;">​</a></h2><p>Narrow-sense overflow router: the input has a strict priority relation between two outputs; B receives no flow until A is too full to accept output.</p><p>Broad-sense overflow router: the input has a non-strict priority relation between two outputs; the flow sent toward A exceeds A&#39;s maximum passable flow rate.</p><p><span id="source-block-S59ZGmLv5iYu3bJX0M4vLU"></span></p><span class="logistics-source-anchor" id="bresenham算法" aria-hidden="true"></span><h2 id="bresenham-algorithm" tabindex="-1">Bresenham Algorithm <a class="header-anchor" href="#bresenham-algorithm" aria-label="Permalink to &quot;Bresenham Algorithm&quot;">​</a></h2><p><span id="source-block-BKd0bfBqMQYjGOon5TjRNh"></span></p><span class="logistics-source-anchor" id="均匀二进制分流器" aria-hidden="true"></span><h2 id="uniform-binary-splitters" tabindex="-1">Uniform Binary Splitters <a class="header-anchor" href="#uniform-binary-splitters" aria-label="Permalink to &quot;Uniform Binary Splitters&quot;">​</a></h2><p><span id="source-block-rJLuoyW0sbNOPnKggEQMI8"></span></p><span class="logistics-source-anchor" id="简单有理分流器的均匀性" aria-hidden="true"></span><h2 id="uniformity-of-simple-rational-splitters" tabindex="-1">Uniformity of Simple Rational Splitters <a class="header-anchor" href="#uniformity-of-simple-rational-splitters" aria-label="Permalink to &quot;Uniformity of Simple Rational Splitters&quot;">​</a></h2><p><span id="source-block-saFuJ384PvuWkO0x5E0uld"></span></p><span class="logistics-source-anchor" id="均匀有理限流器" aria-hidden="true"></span><h2 id="uniform-rational-rate-limiters" tabindex="-1">Uniform Rational-Rate Limiters <a class="header-anchor" href="#uniform-rational-rate-limiters" aria-label="Permalink to &quot;Uniform Rational-Rate Limiters&quot;">​</a></h2><p><span id="source-block-Uj5kS4ulgYdVqCL6baJ4Ku"></span></p><span class="logistics-source-anchor" id="闰年算法" aria-hidden="true"></span><h3 id="leap-year-algorithm" tabindex="-1">Leap-Year Algorithm <a class="header-anchor" href="#leap-year-algorithm" aria-label="Permalink to &quot;Leap-Year Algorithm&quot;">​</a></h3><p><span id="source-block-SmEDFRTyh8P5P9V7gXt3Kh"></span></p><span class="logistics-source-anchor" id="欧拉算法" aria-hidden="true"></span><h3 id="euler-algorithm" tabindex="-1">Euler Algorithm <a class="header-anchor" href="#euler-algorithm" aria-label="Permalink to &quot;Euler Algorithm&quot;">​</a></h3><p><span id="source-block-xQRRd0h5FlKNP3iUeDlYjq"></span></p><span class="logistics-source-anchor" id="古典物流理论" aria-hidden="true"></span><h2 id="classical-logistics-theory" tabindex="-1">Classical Logistics Theory <a class="header-anchor" href="#classical-logistics-theory" aria-label="Permalink to &quot;Classical Logistics Theory&quot;">​</a></h2></div>',1)])])}const f=e(o,[["render",t]]);export{h as __pageData,f as default};
